/* Preview a supplied-source D66 territory draw; add only on explicit confirmation. */
(function(){'use strict';
const E=v=>esc(String(v??'')),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`,account=()=>window.AccountParity?.account?.id||'',tableId='official-003-core-territory-selection-table';
let active=null;
const selected=()=>[...document.querySelectorAll('.cp-territory-modal [name=territoryType]:checked')].map(n=>n.value).sort();
function editable(c){const a=window.AccountParity;if(!c||c.remoteReadOnly||c.remoteRole==='viewer'||a&&(a.connecting||a.busy||a.account&&!a.ready))return false;if((c.remoteOwnerId||c.remoteRole)&&(!a?.account||!a.ready))return false;if(c.remoteOwnerId&&c.remoteOwnerId!==a?.account?.id&&c.remoteRole!=='editor')return false;const probe=document.createElement('button');probe.dataset.cp='territory-new';return !window.SharedCampaignControls?.blocked(probe);}
function source(c,types){if(String(c?.edition).toLowerCase()!=='n26'||cpCampaignType(c)?.id!=='official-003-campaign-necromunda-campaign'||!types.includes(cpCampaignType(c).id))return null;const table=(RULES_DATA.coreRules||[]).find(r=>r.id===tableId&&r.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26'),rows=table?.rule_data?.rows;if(!Array.isArray(rows)||!rows.length)return null;const pool=cpTerritoryRows(c,types),entries=rows.map(r=>({min:Number(r.min),max:Number(r.max),rule:pool.find(t=>t.id===r.territory_id)}));if(entries.some(r=>!r.rule||r.rule.gang_type_id||r.rule.rule_data?.can_be_staked===false||r.rule.rule_data?.cannot_lose===true))return null;for(let a=1;a<=6;a++)for(let b=1;b<=6;b++)if(entries.filter(r=>10*a+b>=r.min&&10*a+b<=r.max).length!==1)return null;return {table,entries,signature:JSON.stringify(entries.map(r=>[r.min,r.max,r.rule.id]))};}
function die(){const a=new Uint32Array(1),limit=4294967292;do{crypto.getRandomValues(a);}while(a[0]>=limit);return a[0]%6+1;}
function roll(entries){const value=10*die()+die();return {value,rule:entries.find(r=>value>=r.min&&value<=r.max)?.rule};}
function live(s){return s&&active===s&&s.root.isConnected&&campaign()===s.c&&account()===s.account&&editable(s.c);}
function say(s,en,ko){const out=s.root.querySelector('[data-td-message]');out.innerHTML=L(en,ko);window.UKI18n?.refresh(out);}
function invalidate(s){s.preview=null;s.root.querySelector('[data-td-results]').innerHTML='';s.root.querySelector('[data-territory-draw=add]').disabled=true;}
function refresh(s){if(!s?.root.isConnected)return;const allowed=editable(s.c),available=!!source(s.c,selected());s.root.querySelector('[data-territory-draw=generate]').disabled=!allowed||!available;s.root.querySelector('[data-td-count]').disabled=!allowed;}
function mount(c){const modal=document.querySelector('.cp-territory-modal'),fieldset=modal?.querySelector('fieldset');if(!modal||!fieldset)return;const root=document.createElement('section');root.className='td-panel';root.innerHTML=`<div class="td-heading"><h3>${L('Random territory draw','영토 무작위 추출')}</h3><button type="button" class="btn small" data-territory-draw="help">${L('Draw rules','추출 룰')}</button></div><p>${L('N26 D66 table · duplicates allowed · Settlement excluded. Preview first, then add to existing territories.','N26 D66 표 · 중복 허용 · 세틀먼트 제외. 결과를 미리 확인한 뒤 기존 영토에 추가합니다.')}</p><div class="td-controls"><label>${L('Number to draw','추출 개수')}<input type="number" min="1" max="120" step="1" value="1" inputmode="numeric" data-td-count></label><button type="button" class="btn" data-territory-draw="generate">${L('Draw / redraw','추출·다시 추출')}</button></div><small>${L('App batch limit: 1–120. Choose a count appropriate for your campaign.','앱의 한 번 처리 범위는 1~120개입니다. 캠페인에 필요한 개수를 직접 정하세요.')}</small><p data-td-message role="status" aria-live="polite">${L('Select Necromunda Campaign above. Previewing does not save any territories.','위에서 네크로문다 캠페인을 선택하세요. 미리보기만으로 영토가 저장되지는 않습니다.')}</p><div data-td-results></div><button type="button" class="btn primary" data-territory-draw="add" disabled>${L('Add drawn territories','추출 영토 추가')}</button>`;fieldset.after(root);active={c,account:account(),root,preview:null};refresh(active);window.UKI18n?.refresh(root);}
const before=cpAddTerritory;cpAddTerritory=function(...args){const result=before.apply(this,args);mount(campaign());return result;};
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-territory-draw]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const s=active;if(!s?.root.isConnected)return;if(b.dataset.territoryDraw==='help'){const src=source(s.c,selected());if(src)window.MMRuleReference?.open('coreRules',tableId,{edition:'n26',activator:b});else say(s,'Verified N26 territory table is unavailable for this selection.','현재 선택에서 검증된 N26 영토 표를 사용할 수 없습니다.');return;}if(!live(s))return say(s,'Access or account changed. Close and reopen the window.','권한 또는 계정이 바뀌었습니다. 창을 닫고 다시 열어 주세요.');const types=selected(),src=source(s.c,types);if(!src){invalidate(s);refresh(s);return say(s,'Select the verified Necromunda Campaign territory table.','검증된 네크로문다 캠페인 영토 표를 선택하세요.');}
if(b.dataset.territoryDraw==='generate'){invalidate(s);const raw=s.root.querySelector('[data-td-count]').value,count=Number(raw);if(!raw||!Number.isSafeInteger(count)||count<1||count>120)return say(s,'Enter a whole number from 1 to 120.','1~120 사이의 정수를 입력하세요.');const draws=Array.from({length:count},()=>roll(src.entries));if(draws.some(d=>!d.rule))return;s.preview={count,types:JSON.stringify(types),signature:src.signature,draws};const groups=new Map();for(const d of draws)groups.set(d.rule.id,{rule:d.rule,count:(groups.get(d.rule.id)?.count||0)+1});s.root.querySelector('[data-td-results]').innerHTML=`<ul class="td-summary">${[...groups.values()].map(g=>`<li>${L(g.rule.name,g.rule.name_ko||g.rule.name)}<strong>× ${g.count}</strong></li>`).join('')}</ul><details class="td-rolls"><summary>${L('D66 results in draw order','추출 순서별 D66 결과')}</summary><ol>${draws.map(d=>`<li>D66 ${d.value} · ${L(d.rule.name,d.rule.name_ko||d.rule.name)}</li>`).join('')}</ol></details>`;s.root.querySelector('[data-territory-draw=add]').disabled=false;say(s,count+' territories previewed. Confirm to add them.','영토 '+count+'개를 미리 추출했습니다. 확인 후 추가하세요.');window.UKI18n?.refresh(s.root);
}else if(b.dataset.territoryDraw==='add'){const p=s.preview,count=Number(s.root.querySelector('[data-td-count]').value);if(!p||p.count!==count||p.types!==JSON.stringify(types)||p.signature!==src.signature){invalidate(s);return say(s,'Selection changed. Draw again before adding.','조건이 바뀌었습니다. 추가하기 전에 다시 추출하세요.');}const records=p.draws.map(d=>{const r=src.entries.find(e=>e.rule.id===d.rule.id)?.rule;if(!r)return null;return {id:id(),name:cpName(r),originalName:cpName(r),territoryId:r.id,gangId:'',playingCard:r.playing_card||'',ruined:false,defaultGangTerritory:false,credits:r.credits??r.income??r.rule_data?.income_credits??null,notes:'',description:r.description||'',randomRoll:d.value};});if(records.some(r=>!r))return;const customDraft=document.querySelector('#cp-custom-territory-name')?.value||'';invalidate(s);s.c.territories.push(...records);cpActivity(s.c,`Random territory draw: ${records.length} territories added`);save();cpAddTerritory(types);const customInput=document.querySelector('#cp-custom-territory-name');if(customInput)customInput.value=customDraft;active.root.querySelector('[data-td-count]').value=String(count);say(active,records.length+' territories added. Existing territories were kept.','추출 영토 '+records.length+'개를 추가했습니다. 기존 영토는 유지됩니다.');}
},true);
document.addEventListener('input',e=>{if(e.target.matches('[data-td-count]')&&active){invalidate(active);say(active,'Count changed. Draw again to preview.','개수가 바뀌었습니다. 다시 추출해 미리보세요.');}});
document.addEventListener('change',e=>{if(e.target.name==='territoryType'&&active?.root.isConnected){invalidate(active);refresh(active);}});
window.MMTerritoryDraw={source,roll,die};
})();
